   if f[fld] is not None and bool(f[fld])!=ctx[fld]: return False
  elif fld=='intracountry':
   if f[fld] is not None and bool(f[fld])!=ctx[fld]: return False
  elif not ok(f[fld],ctx[fld]): return False
 return True

