 print(c,'count',fraud[c], 'tx',cnt[c], 'fraud rate %',100*fraud[c]/cnt[c], 'fraudvol',fvol[c],'volrate',100*fvol[c]/vol[c])
print('top count',fraud.most_common())
print('top rate',sorted(((100*fraud[c]/cnt[c],c) for c in cnt),reverse=True)[:10])
